  (3563, 'sentence', 'S000002360', 'ດອກໄມ້ຫ່ຽວແລ້ວເພາະບໍ່ມີນ້ຳ. The flowers have wilted because there is no water.', 'SRC-AGENT:sequencing', 'derived', null),
  (3564, 'sentence', 'S000002361', 'ຜັກຫ່ຽວເພາະແດດຮ້ອນ. The vegetables are wilting because the sun is hot.', 'SRC-AGENT:sequencing', 'derived', null),
