  (3572, 'sentence', 'S000002366', 'ແມ່ໃຊ້ຈົກຂຸດດິນປູກຜັກ. Mother uses a hoe to dig the soil and plant vegetables.', 'SRC-AGENT:sequencing', 'derived', null),
  (3573, 'sentence', 'S000002367', 'ຈົກດ້າມນີ້ໜັກ. This hoe is heavy.', 'SRC-AGENT:sequencing', 'derived', null),
