  (3580, 'sentence', 'S000002371', 'ພໍ່ໄຖດິນກ່ອນປູກເຂົ້າ. Father ploughs the soil before planting rice.', 'SRC-AGENT:sequencing', 'derived', null),
  (3581, 'sentence', 'S000002372', 'ໄຖຄັນນີ້ເກົ່າ. This plough is old.', 'SRC-AGENT:sequencing', 'derived', null),
  (3582, 'word', 'W001166', 'ຖອນ to pull out; to uproot; to withdraw (word 1166; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3583, 'sentence', 'S000002373', 'ພໍ່ຖອນຕົ້ນໄມ້ນ້ອຍອອກ. Father pulls out the small tree.', 'SRC-AGENT:sequencing', 'derived', null),
