  (3586, 'sentence', 'S000002375', 'ຖອນຫຍ້າເມື່ອຍຫຼາຍ. Pulling weeds is very tiring.', 'SRC-AGENT:sequencing', 'derived', null),
  (3587, 'word', 'W001168', 'ຕັດຫຍ້າ to cut the grass; to mow (word 1168; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3588, 'sentence', 'S000002376', 'ພໍ່ຕັດຫຍ້າທຸກອາທິດ. Father cuts the grass every week.', 'SRC-AGENT:sequencing', 'derived', null),
  (3589, 'sentence', 'S000002377', 'ຫຍ້າຍາວແລ້ວເຮົາຕ້ອງຕັດຫຍ້າ. The grass is long now; we have to cut it.', 'SRC-AGENT:sequencing', 'derived', null),
  (3590, 'word', 'W001169', 'ແມງໄມ້ insect(s) (word 1169; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3591, 'sentence', 'S000002378', 'ມີແມງໄມ້ຫຼາຍໃນສວນ. There are a lot of insects in the garden.', 'SRC-AGENT:sequencing', 'derived', null),
  (3592, 'sentence', 'S000002379', 'ແມງໄມ້ກິນໃບຜັກ. Insects eat the vegetable leaves.', 'SRC-AGENT:sequencing', 'derived', null),
  (3593, 'word', 'W001170', 'ໜອນ worm; caterpillar; larva (word 1170; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3594, 'sentence', 'S000002380', 'ໜອນກິນໃບໄມ້. Caterpillars eat leaves.', 'SRC-AGENT:sequencing', 'derived', null),
  (3595, 'sentence', 'S000002381', 'ມີໜອນສາມໂຕໃນຜັກ. There are three worms in the vegetables.', 'SRC-AGENT:sequencing', 'derived', null),
  (3596, 'word', 'W001171', 'ໄສ້ເດືອນ earthworm (word 1171; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3597, 'sentence', 'S000002382', 'ໄສ້ເດືອນດີສຳລັບດິນ. Earthworms are good for the soil.', 'SRC-AGENT:sequencing', 'derived', null),
  (3598, 'word', 'W001172', 'ຂ້າ to kill; to destroy (word 1172; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3599, 'sentence', 'S000002383', 'ພໍ່ຂ້າງູໃນສວນ. Father killed a snake in the garden.', 'SRC-AGENT:sequencing', 'derived', null),
  (3600, 'sentence', 'S000002384', 'ຂ້ອຍບໍ່ຢາກຂ້າແມງໄມ້. I don''t want to kill the insects.', 'SRC-AGENT:sequencing', 'derived', null),
  (3601, 'word', 'W001173', 'ຢາຂ້າແມງໄມ້ insecticide; pesticide (word 1173; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3602, 'sentence', 'S000002385', 'ຢາຂ້າແມງໄມ້ອັນຕະລາຍ. Pesticide is dangerous.', 'SRC-AGENT:sequencing', 'derived', null),
  (3603, 'sentence', 'S000002386', 'ລ້າງມືຫຼັງຈາກໃຊ້ຢາຂ້າແມງໄມ້. Wash your hands after using pesticide.', 'SRC-AGENT:sequencing', 'derived', null),
  (3604, 'word', 'W001174', 'ຢາຂ້າຫຍ້າ herbicide; weedkiller (word 1174; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3605, 'sentence', 'S000002387', 'ຊາວນາໃຊ້ຢາຂ້າຫຍ້າ. The farmers use weedkiller.', 'SRC-AGENT:sequencing', 'derived', null),
  (3606, 'sentence', 'S000002388', 'ຢາຂ້າຫຍ້າຂວດນີ້ລາຄາແພງ. This bottle of weedkiller is expensive.', 'SRC-AGENT:sequencing', 'derived', null),
  (3607, 'word', 'W001175', 'ສວນຜັກ vegetable garden (word 1175; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3608, 'sentence', 'S000002389', 'ແມ່ມີສວນຜັກນ້ອຍຢູ່ຫຼັງເຮືອນ. Mother has a small vegetable garden behind the house.', 'SRC-AGENT:sequencing', 'derived', null),
  (3609, 'sentence', 'S000002390', 'ຂ້ອຍໃຊ້ນ້ຳສາມຖັງຫົດນ້ຳສວນຜັກ. I use three buckets of water to water the vegetable garden.', 'SRC-AGENT:sequencing', 'derived', null),
  (3610, 'sentence', 'S000002391', 'ມື້ນີ້ຂ້ອຍຕ້ອງຖອນຫຍ້າໃນສວນຜັກ. Today I have to pull the weeds in the vegetable garden.', 'SRC-AGENT:sequencing', 'derived', null),
  (3611, 'word', 'W001176', 'ສວນດອກໄມ້ flower garden (word 1176; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3612, 'sentence', 'S000002392', 'ສວນດອກໄມ້ນີ້ງາມຫຼາຍ. This flower garden is very beautiful.', 'SRC-AGENT:sequencing', 'derived', null),
  (3613, 'sentence', 'S000002393', 'ເຮົາໄປຖ່າຍຮູບຢູ່ສວນດອກໄມ້. We went to take photos at the flower garden.', 'SRC-AGENT:sequencing', 'derived', null),
  (3614, 'word', 'W001177', 'ຊາວສວນ gardener; orchard or market-garden farmer (word 1177; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3615, 'sentence', 'S000002394', 'ລຸງເປັນຊາວສວນ. My uncle is a fruit and vegetable farmer.', 'SRC-AGENT:sequencing', 'derived', null),
  (3616, 'sentence', 'S000002395', 'ຊາວສວນຂາຍໝາກໄມ້ຢູ່ຕະຫຼາດ. The growers sell fruit at the market.', 'SRC-AGENT:sequencing', 'derived', null),
  (3617, 'word', 'W001178', 'ກະສິກຳ agriculture; farming (word 1178; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3618, 'sentence', 'S000002396', 'ກະສິກຳສຳຄັນຫຼາຍສຳລັບປະເທດລາວ. Agriculture is very important for Laos.', 'SRC-AGENT:sequencing', 'derived', null),
  (3619, 'sentence', 'S000002397', 'ເຂົາຮຽນກະສິກຳຢູ່ມະຫາວິທະຍາໄລ. She studies agriculture at university.', 'SRC-AGENT:sequencing', 'derived', null),
  (3620, 'word', 'W001179', 'ເຮັດນາ to farm rice; to work the rice fields (word 1179; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3621, 'sentence', 'S000002398', 'ຄອບຄົວຂ້ອຍເຮັດນາ. My family farms rice.', 'SRC-AGENT:sequencing', 'derived', null),
  (3622, 'sentence', 'S000002399', 'ພໍ່ແມ່ຂ້ອຍເຮັດນາຢູ່ບ້ານ. My parents farm rice in the village.', 'SRC-AGENT:sequencing', 'derived', null),
  (3623, 'word', 'W001180', 'ດຳນາ to transplant rice seedlings (word 1180; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3624, 'sentence', 'S000002400', 'ເຮົາດຳນາໃນເດືອນກໍລະກົດ. We transplant the rice in July.', 'SRC-AGENT:sequencing', 'derived', null),
  (3625, 'sentence', 'S000002401', 'ຊາວນາເອົາກ້າໄປດຳນາ. The farmers take the seedlings to plant out in the paddies.', 'SRC-AGENT:sequencing', 'derived', null),
  (3626, 'word', 'W001181', 'ໄຖນາ to plough the rice fields (word 1181; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3627, 'sentence', 'S000002402', 'ຊາວນາໃຊ້ຄວາຍໄຖນາ. Farmers use buffalo to plough the rice fields.', 'SRC-AGENT:sequencing', 'derived', null),
  (3628, 'sentence', 'S000002403', 'ເດືອນໜ້າເຮົາຈະໄຖນາ. Next month we will plough the fields.', 'SRC-AGENT:sequencing', 'derived', null),
  (3629, 'word', 'W001182', 'ຕົ້ນເຂົ້າ rice plant (word 1182; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3630, 'sentence', 'S000002404', 'ຕົ້ນເຂົ້າສູງຂຶ້ນແລ້ວ. The rice plants have grown taller.', 'SRC-AGENT:sequencing', 'derived', null),
  (3631, 'sentence', 'S000002405', 'ຕົ້ນເຂົ້າຕ້ອງການນ້ຳຫຼາຍ. Rice plants need a lot of water.', 'SRC-AGENT:sequencing', 'derived', null),
