  (3633, 'sentence', 'S000002406', 'ຊາວນາຕາກເຂົ້າເປືອກໃຫ້ແຫ້ງ. The farmers dry the paddy in the sun.', 'SRC-AGENT:sequencing', 'derived', null),
  (3634, 'sentence', 'S000002407', 'ເຮົາມີເຂົ້າເປືອກສິບຖົງ. We have ten sacks of paddy.', 'SRC-AGENT:sequencing', 'derived', null),
  (3635, 'word', 'W001184', 'ເຂົ້າສານ milled rice (husked; uncooked) (word 1184; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3636, 'sentence', 'S000002408', 'ແມ່ຊື້ເຂົ້າສານຫ້າກິໂລ. Mother bought five kilos of rice.', 'SRC-AGENT:sequencing', 'derived', null),
  (3637, 'sentence', 'S000002409', 'ເຂົ້າສານໝົດແລ້ວ. The rice has run out.', 'SRC-AGENT:sequencing', 'derived', null),
