  (3639, 'sentence', 'S000002410', 'ຊາວນາກ່ຽວເຂົ້າໃນເດືອນພະຈິກ. Farmers reap the rice in November.', 'SRC-AGENT:sequencing', 'derived', null),
  (3640, 'sentence', 'S000002411', 'ພໍ່ໃຊ້ກ່ຽວຕັດຫຍ້າ. Father uses a sickle to cut the grass.', 'SRC-AGENT:sequencing', 'derived', null),
  (3641, 'word', 'W001186', 'ເກັບກ່ຽວ to harvest (word 1186; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3642, 'sentence', 'S000002412', 'ເຮົາຈະເກັບກ່ຽວເມື່ອໃດ? When will we harvest?', 'SRC-AGENT:sequencing', 'derived', null),
  (3643, 'sentence', 'S000002413', 'ປີນີ້ເກັບກ່ຽວໄດ້ຫຼາຍ. We harvested a lot this year.', 'SRC-AGENT:sequencing', 'derived', null),
  (3644, 'word', 'W001187', 'ທົ່ງ field; plain; meadow (word 1187; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3645, 'sentence', 'S000002414', 'ທົ່ງນາຂຽວງາມ. The rice fields are green and beautiful.', 'SRC-AGENT:sequencing', 'derived', null),
  (3646, 'sentence', 'S000002415', 'ຄວາຍກິນຫຍ້າຢູ່ໃນທົ່ງ. The buffalo are eating grass in the field.', 'SRC-AGENT:sequencing', 'derived', null),
  (3647, 'word', 'W001188', 'ຄັນນາ dike; earth bank between rice paddies (word 1188; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3648, 'sentence', 'S000002416', 'ເດັກຍ່າງຢູ່ເທິງຄັນນາ. The children are walking along the paddy dike.', 'SRC-AGENT:sequencing', 'derived', null),
  (3649, 'sentence', 'S000002417', 'ຄັນນາແຄບແລະປຽກ. The paddy dike is narrow and wet.', 'SRC-AGENT:sequencing', 'derived', null),
  (3650, 'word', 'W001189', 'ຕົມ mud; dirt (word 1189; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3651, 'sentence', 'S000002418', 'ຂ້ອຍເຫັນໄສ້ເດືອນໃນຕົມ. I see an earthworm in the mud.', 'SRC-AGENT:sequencing', 'derived', null),
  (3652, 'sentence', 'S000002419', 'ຕີນຂ້ອຍເປື້ອນຕົມ. My feet are muddy.', 'SRC-AGENT:sequencing', 'derived', null),
  (3653, 'word', 'W001190', 'ໄຮ່ upland field; dry hillside field (often slash-and-burn) (word 1190; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3654, 'sentence', 'S000002420', 'ຄົນບ້ານນີ້ເຮັດໄຮ່ຢູ່ເທິງພູ. The people of this village farm upland fields on the mountain.', 'SRC-AGENT:sequencing', 'derived', null),
  (3655, 'sentence', 'S000002421', 'ເຂົາປູກເຂົ້າໃນໄຮ່. They grow rice in upland fields.', 'SRC-AGENT:sequencing', 'derived', null),
  (3656, 'word', 'W001191', 'ແລ້ງ dry (without rain); in drought (word 1191; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3657, 'sentence', 'S000002422', 'ປີນີ້ແລ້ງຫຼາຍ. It is very dry this year.', 'SRC-AGENT:sequencing', 'derived', null),
  (3658, 'sentence', 'S000002423', 'ຖ້າແລ້ງຕົ້ນເຂົ້າຈະຕາຍ. If it is dry, the rice plants will die.', 'SRC-AGENT:sequencing', 'derived', null),
  (3659, 'word', 'W001192', 'ຊຸ່ມ moist; damp (word 1192; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3660, 'sentence', 'S000002424', 'ດິນຍັງຊຸ່ມບໍ່ຕ້ອງຫົດນ້ຳ. The soil is still moist; there''s no need to water.', 'SRC-AGENT:sequencing', 'derived', null),
  (3661, 'sentence', 'S000002425', 'ຫຼັງຈາກຝົນຕົກດິນຊຸ່ມດີ. After the rain, the soil is nicely moist.', 'SRC-AGENT:sequencing', 'derived', null),
  (3662, 'word', 'W001193', 'ກະຖາງ flowerpot; plant pot (word 1193; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3663, 'sentence', 'S000002426', 'ແມ່ປູກດອກໄມ້ໃນກະຖາງ. Mother plants flowers in pots.', 'SRC-AGENT:sequencing', 'derived', null),
  (3664, 'sentence', 'S000002427', 'ຂ້ອຍຊື້ກະຖາງສອງໜ່ວຍ. I bought two flowerpots.', 'SRC-AGENT:sequencing', 'derived', null),
  (3665, 'word', 'W001194', 'ຖົ່ວ bean; pea; nut (legume) (word 1194; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3666, 'sentence', 'S000002428', 'ຂ້ອຍມັກກິນຖົ່ວ. I like eating beans.', 'SRC-AGENT:sequencing', 'derived', null),
  (3667, 'sentence', 'S000002429', 'ແມ່ຕົ້ມຖົ່ວໃນໝໍ້. Mother boils beans in a pot.', 'SRC-AGENT:sequencing', 'derived', null),
  (3668, 'word', 'W001195', 'ໝາກຖົ່ວ beans (in the pod); yard-long beans (word 1195; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3669, 'sentence', 'S000002430', 'ແມ່ຊື້ໝາກຖົ່ວສອງມັດ. Mother bought two bundles of long beans.', 'SRC-AGENT:sequencing', 'derived', null),
  (3670, 'sentence', 'S000002431', 'ຂ້ອຍກິນຕຳໝາກຫຸ່ງກັບໝາກຖົ່ວ. I eat papaya salad with long beans.', 'SRC-AGENT:sequencing', 'derived', null),
  (3671, 'word', 'W001196', 'ຖົ່ວດິນ peanut (word 1196; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3672, 'sentence', 'S000002432', 'ຖົ່ວດິນກິໂລນີ້ລາຄາເທົ່າໃດ? How much is this kilo of peanuts?', 'SRC-AGENT:sequencing', 'derived', null),
  (3673, 'sentence', 'S000002433', 'ພໍ່ປູກຖົ່ວດິນຢູ່ໃນໄຮ່. Father grows peanuts in the upland field.', 'SRC-AGENT:sequencing', 'derived', null),
  (3674, 'word', 'W001197', 'ຖົ່ວເຫຼືອງ soybean (word 1197; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3675, 'sentence', 'S000002434', 'ນົມນີ້ເຮັດຈາກຖົ່ວເຫຼືອງ. This milk is made from soybeans.', 'SRC-AGENT:sequencing', 'derived', null),
  (3676, 'sentence', 'S000002435', 'ຊາວນາປູກຖົ່ວເຫຼືອງໃນລະດູແລ້ງ. Farmers grow soybeans in the dry season.', 'SRC-AGENT:sequencing', 'derived', null),
  (3677, 'word', 'W001198', 'ຖົ່ວຂຽວ mung bean (word 1198; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3678, 'sentence', 'S000002436', 'ແມ່ເຮັດຂອງຫວານຈາກຖົ່ວຂຽວ. Mother makes a dessert from mung beans.', 'SRC-AGENT:sequencing', 'derived', null),
  (3679, 'word', 'W001199', 'ຖົ່ວງອກ bean sprouts (word 1199; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3680, 'sentence', 'S000002438', 'ເຝີຖ້ວຍນີ້ມີຖົ່ວງອກຫຼາຍ. This bowl of pho has a lot of bean sprouts.', 'SRC-AGENT:sequencing', 'derived', null),
  (3681, 'sentence', 'S000002439', 'ຂໍຖົ່ວງອກສົດແດ່. Fresh bean sprouts, please.', 'SRC-AGENT:sequencing', 'derived', null),
  (3682, 'word', 'W001200', 'ຝັກ pod; ear (of corn); classifier for pods and corn cobs (word 1200; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3683, 'sentence', 'S000002440', 'ໝາກຖົ່ວຝັກນີ້ຍາວຫຼາຍ. This bean pod is very long.', 'SRC-AGENT:sequencing', 'derived', null),
  (3684, 'word', 'W001201', 'ເຫັດ mushroom (word 1201; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3685, 'sentence', 'S000002442', 'ເຫັດນີ້ກິນໄດ້ບໍ່? Can this mushroom be eaten?', 'SRC-AGENT:sequencing', 'derived', null),
  (3686, 'sentence', 'S000002443', 'ໃນລະດູຝົນມີເຫັດຫຼາຍຢູ່ໃນປ່າ. In the rainy season, there are many mushrooms in the forest.', 'SRC-AGENT:sequencing', 'derived', null),
  (3687, 'word', 'W001202', 'ເຫັດຫູໜູ wood ear mushroom (black fungus) (word 1202; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3688, 'sentence', 'S000002444', 'ແມ່ໃສ່ເຫັດຫູໜູໃນແກງ. Mother puts wood ear mushrooms in the soup.', 'SRC-AGENT:sequencing', 'derived', null),
  (3689, 'sentence', 'S000002445', 'ເຫັດຫູໜູມີສີດຳ. Wood ear mushrooms are black.', 'SRC-AGENT:sequencing', 'derived', null),
  (3690, 'word', 'W001203', 'ເຫັດຫອມ shiitake mushroom (word 1203; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3691, 'sentence', 'S000002446', 'ເຫັດຫອມແຫ້ງລາຄາແພງ. Dried shiitake mushrooms are expensive.', 'SRC-AGENT:sequencing', 'derived', null),
  (3692, 'sentence', 'S000002447', 'ຂ້ອຍຂົ້ວເຫັດຫອມກັບຜັກ. I stir-fry shiitake mushrooms with vegetables.', 'SRC-AGENT:sequencing', 'derived', null),
  (3693, 'word', 'W001204', 'ເຫັດເຟືອງ straw mushroom (word 1204; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3694, 'sentence', 'S000002448', 'ເຫັດເຟືອງໃສ່ແກງແຊບຫຼາຍ. Straw mushrooms in soup are delicious.', 'SRC-AGENT:sequencing', 'derived', null),
  (3695, 'sentence', 'S000002449', 'ແມ່ຄ້າຂາຍເຫັດເຟືອງສົດຢູ່ຕະຫຼາດເຊົ້າ. The vendor sells fresh straw mushrooms at the morning market.', 'SRC-AGENT:sequencing', 'derived', null),
  (3696, 'word', 'W001205', 'ເຫັດປວກ termite mushroom (wild mushroom of the rainy season) (word 1205; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3697, 'sentence', 'S000002450', 'ເຫັດປວກມີແຕ່ໃນລະດູຝົນ. Termite mushrooms are only found in the rainy season.', 'SRC-AGENT:sequencing', 'derived', null),
  (3698, 'sentence', 'S000002451', 'ຍາຍເກັບເຫັດປວກຢູ່ໃນປ່າ. Grandma gathers termite mushrooms in the forest.', 'SRC-AGENT:sequencing', 'derived', null),
  (3699, 'word', 'W001206', 'ໜໍ່ shoot; sprout (esp. bamboo shoot); classifier for shoots (word 1206; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3700, 'sentence', 'S000002452', 'ໄຜ່ມີໜໍ່ໃໝ່ຫຼາຍໃນລະດູຝົນ. The bamboo has many new shoots in the rainy season.', 'SRC-AGENT:sequencing', 'derived', null),
  (3701, 'sentence', 'S000002453', 'ພໍ່ຂຸດໜໍ່ໄຜ່ຢູ່ຫຼັງເຮືອນ. Father digs up bamboo shoots behind the house.', 'SRC-AGENT:sequencing', 'derived', null),
  (3702, 'word', 'W001207', 'ໜໍ່ໄມ້ bamboo shoot (word 1207; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3703, 'sentence', 'S000002454', 'ແມ່ເຮັດແກງໜໍ່ໄມ້. Mother makes bamboo shoot soup.', 'SRC-AGENT:sequencing', 'derived', null),
  (3704, 'sentence', 'S000002455', 'ໜໍ່ໄມ້ຕ້ອງຕົ້ມກ່ອນກິນ. Bamboo shoots must be boiled before eating.', 'SRC-AGENT:sequencing', 'derived', null),
  (3705, 'word', 'W001208', 'ສາລີ corn; maize (word 1208; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3706, 'sentence', 'S000002441', 'ຂ້ອຍຊື້ສາລີສາມຝັກ. I bought three ears of corn.', 'SRC-AGENT:sequencing', 'derived', null),
  (3707, 'sentence', 'S000002456', 'ສາລີຕົ້ມຫວານແລະອ່ອນ. Boiled corn is sweet and soft.', 'SRC-AGENT:sequencing', 'derived', null),
  (3708, 'word', 'W001209', 'ໝາກເຂືອ eggplant; aubergine (word 1209; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3709, 'sentence', 'S000002457', 'ຂ້ອຍປີ້ງໝາກເຂືອເພື່ອເຮັດແຈ່ວ. I grill eggplants to make jeow.', 'SRC-AGENT:sequencing', 'derived', null),
  (3710, 'sentence', 'S000002458', 'ໝາກເຂືອໜ່ວຍນ້ອຍມີສີຂຽວ. The small eggplants are green.', 'SRC-AGENT:sequencing', 'derived', null),
  (3711, 'word', 'W001210', 'ໝາກອຶ pumpkin (word 1210; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3712, 'sentence', 'S000002459', 'ໝາກອຶໜ່ວຍນີ້ໃຫຍ່ຫຼາຍ. This pumpkin is very big.', 'SRC-AGENT:sequencing', 'derived', null),
  (3713, 'sentence', 'S000002460', 'ແມ່ຕົ້ມໝາກອຶກັບກະທິ. Mother boils pumpkin with coconut milk.', 'SRC-AGENT:sequencing', 'derived', null),
  (3714, 'word', 'W001211', 'ໝາກບວບ luffa; sponge gourd (word 1211; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3715, 'sentence', 'S000002461', 'ພໍ່ປູກໝາກບວບໃກ້ຮົ້ວ. Father grows luffa near the fence.', 'SRC-AGENT:sequencing', 'derived', null),
  (3716, 'sentence', 'S000002462', 'ໝາກບວບຂົ້ວກັບໄຂ່ແຊບຫຼາຍ. Luffa stir-fried with egg is very tasty.', 'SRC-AGENT:sequencing', 'derived', null),
  (3717, 'word', 'W001212', 'ຜັກກາດ mustard greens; leafy greens of the cabbage family (word 1212; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3718, 'sentence', 'S000002463', 'ແມ່ຄ້າຂາຍຜັກກາດມັດລະຫ້າພັນກີບ. The vendor sells mustard greens at five thousand kip a bundle.', 'SRC-AGENT:sequencing', 'derived', null),
  (3719, 'sentence', 'S000002464', 'ຂ້ອຍລ້າງຜັກກາດກ່ອນແຕ່ງກິນ. I wash the greens before cooking.', 'SRC-AGENT:sequencing', 'derived', null),
  (3720, 'word', 'W001213', 'ຜັກກາດຂາວ Chinese cabbage; napa cabbage (word 1213; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3721, 'sentence', 'S000002465', 'ຜັກກາດຂາວຫົວນີ້ໜັກຫຼາຍ. This Chinese cabbage is very heavy.', 'SRC-AGENT:sequencing', 'derived', null),
  (3722, 'sentence', 'S000002466', 'ຂ້ອຍໃສ່ຜັກກາດຂາວໃນແກງ. I put Chinese cabbage in the soup.', 'SRC-AGENT:sequencing', 'derived', null),
  (3723, 'word', 'W001214', 'ກະລຳປີ cabbage (word 1214; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3724, 'sentence', 'S000002467', 'ກະລຳປີສອງຫົວລາຄາເທົ່າໃດ? How much are two cabbages?', 'SRC-AGENT:sequencing', 'derived', null),
  (3725, 'word', 'W001215', 'ຜັກບົ້ງ morning glory; water spinach (word 1215; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3726, 'sentence', 'S000002469', 'ຜັກບົ້ງຂົ້ວແມ່ນອາຫານທີ່ຂ້ອຍມັກ. Stir-fried morning glory is a dish I like.', 'SRC-AGENT:sequencing', 'derived', null),
  (3727, 'sentence', 'S000002470', 'ຜັກບົ້ງຂຶ້ນໄວຢູ່ແຄມໜອງ. Morning glory grows fast at the edge of the pond.', 'SRC-AGENT:sequencing', 'derived', null),
  (3728, 'word', 'W001216', 'ຜັກຫວານ sweet leaf (Sauropus; a leafy vegetable) (word 1216; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3729, 'sentence', 'S000002471', 'ແມ່ເຮັດແກງຜັກຫວານໃສ່ໄຂ່. Mother makes sweet leaf soup with egg.', 'SRC-AGENT:sequencing', 'derived', null),
  (3730, 'sentence', 'S000002472', 'ຍາຍເກັບຍອດຜັກຫວານຢູ່ຫຼັງເຮືອນ. Grandma picks sweet leaf shoots behind the house.', 'SRC-AGENT:sequencing', 'derived', null),
  (3731, 'word', 'W001217', 'ຜັກກູດ edible fern shoots; fiddlehead fern (word 1217; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3732, 'sentence', 'S000002473', 'ຜັກກູດຂຶ້ນຢູ່ແຄມຫ້ວຍ. Fern shoots grow along the stream.', 'SRC-AGENT:sequencing', 'derived', null),
  (3733, 'word', 'W001218', 'ຜັກຊີ dill (word 1218; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3734, 'sentence', 'S000002475', 'ຂໍໃສ່ຜັກຊີໃນແກງປາແດ່. Please put dill in the fish soup.', 'SRC-AGENT:sequencing', 'derived', null),
  (3735, 'word', 'W001219', 'ກາລົດ carrot (word 1219; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3736, 'sentence', 'S000002477', 'ກາລົດມີສີສົ້ມ. Carrots are orange.', 'SRC-AGENT:sequencing', 'derived', null),
  (3737, 'word', 'W001220', 'ຫົວຜັກກາດ radish; daikon (word 1220; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3738, 'sentence', 'S000002479', 'ແມ່ຕົ້ມຫົວຜັກກາດກັບຊີ້ນໝູ. Mother boils radish with pork.', 'SRC-AGENT:sequencing', 'derived', null),
  (3739, 'sentence', 'S000002480', 'ຫົວຜັກກາດມີສີຂາວ. Radishes are white.', 'SRC-AGENT:sequencing', 'derived', null),
  (3740, 'word', 'W001221', 'ມັນຕົ້ນ cassava (word 1221; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3741, 'sentence', 'S000002482', 'ຊາວນາປູກມັນຕົ້ນຢູ່ໃນໄຮ່. Farmers plant cassava in the upland fields.', 'SRC-AGENT:sequencing', 'derived', null),
  (3742, 'word', 'W001222', 'ມັນດ້າງ sweet potato (word 1222; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3743, 'sentence', 'S000002483', 'ເດັກມັກກິນມັນດ້າງປີ້ງ. Children like eating grilled sweet potatoes.', 'SRC-AGENT:sequencing', 'derived', null),
  (3744, 'sentence', 'S000002484', 'ມັນດ້າງນີ້ຫວານຫຼາຍ. This sweet potato is very sweet.', 'SRC-AGENT:sequencing', 'derived', null),
