  (3746, 'sentence', 'S000002485', 'ເຜືອກຕົ້ມແຊບຫຼາຍ. Boiled taro is very tasty.', 'SRC-AGENT:sequencing', 'derived', null),
  (3747, 'sentence', 'S000002486', 'ແມ່ເຮັດຂອງຫວານຈາກເຜືອກແລະກະທິ. Mother makes a dessert from taro and coconut milk.', 'SRC-AGENT:sequencing', 'derived', null),
  (3748, 'word', 'W001224', 'ສີໄຄ lemongrass (word 1224; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3749, 'word', 'W001225', 'ຂ່າ galangal (word 1225; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3750, 'sentence', 'S000002487', 'ຂ້ອຍໃສ່ສີໄຄແລະຂ່າໃນແກງ. I put lemongrass and galangal in the soup.', 'SRC-AGENT:sequencing', 'derived', null),
  (3751, 'word', 'W001226', 'ຂະໝິ້ນ turmeric (word 1226; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3752, 'sentence', 'S000002490', 'ຂະໝິ້ນມີສີເຫຼືອງ. Turmeric is yellow.', 'SRC-AGENT:sequencing', 'derived', null),
  (3753, 'sentence', 'S000002491', 'ແມ່ໃສ່ຂະໝິ້ນໃນແກງໄກ່. Mother puts turmeric in the chicken curry.', 'SRC-AGENT:sequencing', 'derived', null),
  (3754, 'word', 'W001227', 'ໂຫລະພາ Thai basil; sweet basil (word 1227; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3755, 'sentence', 'S000002492', 'ຂ້ອຍກິນເຝີກັບໂຫລະພາ. I eat pho with basil.', 'SRC-AGENT:sequencing', 'derived', null),
  (3756, 'sentence', 'S000002493', 'ໂຫລະພາມັດນີ້ສົດຫຼາຍ. This bunch of basil is very fresh.', 'SRC-AGENT:sequencing', 'derived', null),
  (3757, 'word', 'W001228', 'ຫອມແດງ shallot (word 1228; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3758, 'sentence', 'S000002495', 'ຂໍຫອມແດງສາມຫົວແດ່. Three shallots, please.', 'SRC-AGENT:sequencing', 'derived', null),
  (3759, 'word', 'W001229', 'ງາ sesame (word 1229; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3760, 'sentence', 'S000002496', 'ຂ້ອຍໃສ່ງາໃນເຂົ້າໜົມ. I put sesame in the snack.', 'SRC-AGENT:sequencing', 'derived', null),
  (3761, 'sentence', 'S000002497', 'ງາມີສອງສີຂາວແລະດຳ. Sesame comes in two colours, white and black.', 'SRC-AGENT:sequencing', 'derived', null),
  (3762, 'word', 'W001230', 'ກ້ານ stalk; stem (of a leaf or fruit) (word 1230; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3763, 'sentence', 'S000002498', 'ແມ່ຕັດກ້ານຜັກອອກ. Mother cuts off the vegetable stalks.', 'SRC-AGENT:sequencing', 'derived', null),
  (3764, 'sentence', 'S000002499', 'ກ້ານໝາກໄມ້ນີ້ຍັງຂຽວ. The stem of this fruit is still green.', 'SRC-AGENT:sequencing', 'derived', null),
  (3765, 'word', 'W001231', 'ໝາກຂາມ tamarind (word 1231; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3766, 'sentence', 'S000002500', 'ໝາກຂາມນີ້ສົ້ມຫຼາຍ. This tamarind is very sour.', 'SRC-AGENT:sequencing', 'derived', null),
  (3767, 'sentence', 'S000002501', 'ແມ່ໃສ່ໝາກຂາມໃນແກງປາ. Mother puts tamarind in the fish soup.', 'SRC-AGENT:sequencing', 'derived', null),
  (3768, 'word', 'W001232', 'ໝາກຂາມຫວານ sweet tamarind (word 1232; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3769, 'sentence', 'S000002502', 'ໝາກຂາມຫວານແກະເປືອກງ່າຍ. Sweet tamarind is easy to peel.', 'SRC-AGENT:sequencing', 'derived', null),
  (3770, 'sentence', 'S000002503', 'ຂ້ອຍຊື້ໝາກຂາມຫວານເປັນຂອງຝາກ. I bought sweet tamarind as a gift.', 'SRC-AGENT:sequencing', 'derived', null),
  (3771, 'word', 'W001233', 'ໝາກລຳໄຍ longan (word 1233; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3772, 'sentence', 'S000002505', 'ຂ້ອຍຊື້ໝາກລຳໄຍສອງກິໂລ. I bought two kilos of longans.', 'SRC-AGENT:sequencing', 'derived', null),
  (3773, 'word', 'W001234', 'ໝາກລິ້ນຈີ່ lychee (word 1234; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3774, 'sentence', 'S000002506', 'ໝາກລິ້ນຈີ່ມີເປືອກສີແດງ. Lychees have red skin.', 'SRC-AGENT:sequencing', 'derived', null),
  (3775, 'sentence', 'S000002507', 'ນ້ຳໝາກລິ້ນຈີ່ເຢັນແຊບຫຼາຍ. Cold lychee juice is delicious.', 'SRC-AGENT:sequencing', 'derived', null),
  (3776, 'word', 'W001235', 'ໝາກເງາະ rambutan (word 1235; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3777, 'sentence', 'S000002508', 'ໝາກເງາະໜ່ວຍນີ້ສຸກແລ້ວ. This rambutan is ripe.', 'SRC-AGENT:sequencing', 'derived', null),
  (3778, 'sentence', 'S000002509', 'ແມ່ຄ້າຂາຍໝາກເງາະກິໂລລະສິບພັນກີບ. The vendor sells rambutans at ten thousand kip a kilo.', 'SRC-AGENT:sequencing', 'derived', null),
  (3779, 'word', 'W001236', 'ໝາກມັງຄຸດ mangosteen (word 1236; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3780, 'sentence', 'S000002510', 'ໝາກມັງຄຸດມີເປືອກສີມ່ວງ. Mangosteens have purple skin.', 'SRC-AGENT:sequencing', 'derived', null),
  (3781, 'sentence', 'S000002511', 'ຂ້ອຍມັກໝາກມັງຄຸດຫຼາຍກວ່າໝາກເງາະ. I like mangosteens more than rambutans.', 'SRC-AGENT:sequencing', 'derived', null),
  (3782, 'word', 'W001237', 'ໝາກທຸລຽນ durian (word 1237; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3783, 'sentence', 'S000002512', 'ໝາກທຸລຽນມີໜາມຫຼາຍ. Durians have a lot of thorns.', 'SRC-AGENT:sequencing', 'derived', null),
  (3784, 'word', 'W001238', 'ໝາກມີ້ jackfruit (word 1238; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3785, 'sentence', 'S000002514', 'ໝາກມີ້ໜ່ວຍນີ້ໃຫຍ່ແລະໜັກ. This jackfruit is big and heavy.', 'SRC-AGENT:sequencing', 'derived', null),
  (3786, 'word', 'W001239', 'ໝາກຂຽບ custard apple; sugar apple (word 1239; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3787, 'sentence', 'S000002516', 'ໝາກຂຽບມີແກ່ນສີດຳຫຼາຍ. Custard apples have a lot of black seeds.', 'SRC-AGENT:sequencing', 'derived', null),
  (3788, 'sentence', 'S000002517', 'ໝາກຂຽບນີ້ອ່ອນແລະຫວານ. This custard apple is soft and sweet.', 'SRC-AGENT:sequencing', 'derived', null),
  (3789, 'word', 'W001240', 'ໝາກສີດາ guava (word 1240; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3790, 'sentence', 'S000002518', 'ຂ້ອຍກິນໝາກສີດາກັບເກືອແລະໝາກເຜັດ. I eat guava with salt and chili.', 'SRC-AGENT:sequencing', 'derived', null),
  (3791, 'word', 'W001241', 'ໝາກລະມຸດ sapodilla (word 1241; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3792, 'sentence', 'S000002520', 'ໝາກລະມຸດມີເປືອກສີນ້ຳຕານ. Sapodillas have brown skin.', 'SRC-AGENT:sequencing', 'derived', null),
  (3793, 'sentence', 'S000002521', 'ໝາກລະມຸດສຸກຫວານຄືກັບນ້ຳຕານ. Ripe sapodilla is as sweet as sugar.', 'SRC-AGENT:sequencing', 'derived', null),
  (3794, 'word', 'W001242', 'ໝາກມັງກອນ dragon fruit (word 1242; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3795, 'sentence', 'S000002522', 'ໝາກມັງກອນມີເປືອກສີບົວ. Dragon fruit has pink skin.', 'SRC-AGENT:sequencing', 'derived', null),
  (3796, 'word', 'W001243', 'ໝາກອະງຸ່ນ grapes (word 1243; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3797, 'sentence', 'S000002525', 'ໝາກອະງຸ່ນສີຂຽວສົ້ມກວ່າໝາກອະງຸ່ນສີມ່ວງ. Green grapes are more sour than purple grapes.', 'SRC-AGENT:sequencing', 'derived', null),
  (3798, 'word', 'W001244', 'ໝາກໂປມ apple (word 1244; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3799, 'sentence', 'S000002526', 'ໝາກໂປມມາຈາກຈີນ. The apples come from China.', 'SRC-AGENT:sequencing', 'derived', null),
  (3800, 'sentence', 'S000002527', 'ເດັກກິນໝາກໂປມສີແດງໜຶ່ງໜ່ວຍ. The child ate one red apple.', 'SRC-AGENT:sequencing', 'derived', null),
  (3801, 'word', 'W001245', 'ໝາກສົ້ມໂອ pomelo (word 1245; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3802, 'sentence', 'S000002528', 'ໝາກສົ້ມໂອໃຫຍ່ກວ່າໝາກກ້ຽງ. A pomelo is bigger than an orange.', 'SRC-AGENT:sequencing', 'derived', null),
  (3803, 'sentence', 'S000002529', 'ແມ່ແກະໝາກສົ້ມໂອໃຫ້ລູກ. Mother peels a pomelo for her child.', 'SRC-AGENT:sequencing', 'derived', null),
  (3804, 'word', 'W001246', 'ໝາກຫວ້າ Java plum; black plum (Syzygium cumini) (word 1246; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3805, 'sentence', 'S000002530', 'ໝາກຫວ້າສຸກມີສີດຳ. Ripe Java plums are black.', 'SRC-AGENT:sequencing', 'derived', null),
  (3806, 'sentence', 'S000002531', 'ເດັກເກັບໝາກຫວ້າໃກ້ແມ່ນ້ຳ. The children gather Java plums near the river.', 'SRC-AGENT:sequencing', 'derived', null),
  (3807, 'word', 'W001247', 'ໝາກໄຟ Burmese grape (Baccaurea) (word 1247; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3808, 'sentence', 'S000002532', 'ໝາກໄຟມີລົດຊາດສົ້ມແລະຫວານ. Burmese grapes taste sour and sweet.', 'SRC-AGENT:sequencing', 'derived', null),
  (3809, 'sentence', 'S000002533', 'ຍາຍຂາຍໝາກໄຟຢູ່ຕະຫຼາດ. Grandma sells Burmese grapes at the market.', 'SRC-AGENT:sequencing', 'derived', null),
  (3810, 'word', 'W001248', 'ໝາກຂີ້ຫູດ kaffir lime (makrut lime) (word 1248; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3811, 'sentence', 'S000002534', 'ແມ່ໃສ່ໃບໝາກຂີ້ຫູດໃນແກງ. Mother puts kaffir lime leaves in the soup.', 'SRC-AGENT:sequencing', 'derived', null),
  (3812, 'sentence', 'S000002535', 'ສວນຂອງຍາຍມີຕົ້ນໝາກຂີ້ຫູດ. Grandma''s garden has a kaffir lime tree.', 'SRC-AGENT:sequencing', 'derived', null),
  (3813, 'word', 'W001249', 'ອ້ອຍ sugarcane (word 1249; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3814, 'sentence', 'S000002536', 'ເດັກມັກກິນອ້ອຍ. Children like eating sugarcane.', 'SRC-AGENT:sequencing', 'derived', null),
  (3815, 'sentence', 'S000002537', 'ນ້ຳຕານເຮັດຈາກອ້ອຍ. Sugar is made from sugarcane.', 'SRC-AGENT:sequencing', 'derived', null),
  (3816, 'word', 'W001250', 'ກ້ວຍຫອມ fragrant banana (Cavendish-type sweet banana) (word 1250; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3817, 'sentence', 'S000002538', 'ກ້ວຍຫອມສຸກມີສີເຫຼືອງ. Ripe fragrant bananas are yellow.', 'SRC-AGENT:sequencing', 'derived', null),
  (3818, 'sentence', 'S000002539', 'ຂ້ອຍຊື້ກ້ວຍຫອມຫ້າໜ່ວຍ. I bought five fragrant bananas.', 'SRC-AGENT:sequencing', 'derived', null),
  (3819, 'word', 'W001251', 'ສວນໝາກໄມ້ orchard; fruit garden (word 1251; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3820, 'sentence', 'S000002540', 'ລຸງມີສວນໝາກໄມ້ໃຫຍ່. Uncle has a big orchard.', 'SRC-AGENT:sequencing', 'derived', null),
  (3821, 'sentence', 'S000002541', 'ໃນສວນໝາກໄມ້ມີຕົ້ນໝາກມ່ວງແລະໝາກມີ້. In the orchard there are mango and jackfruit trees.', 'SRC-AGENT:sequencing', 'derived', null),
  (3822, 'word', 'W001252', 'ພວງ bunch; cluster; classifier for bunches (grapes; longans; flowers) (word 1252; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3823, 'sentence', 'S000002504', 'ໝາກລຳໄຍພວງນີ້ຫວານຫຼາຍ. This bunch of longans is very sweet.', 'SRC-AGENT:sequencing', 'derived', null),
  (3824, 'sentence', 'S000002524', 'ໝາກອະງຸ່ນພວງນີ້ລາຄາແພງ. This bunch of grapes is expensive.', 'SRC-AGENT:sequencing', 'derived', null),
  (3825, 'sentence', 'S000002542', 'ຂໍໝາກອະງຸ່ນສອງພວງແດ່. Two bunches of grapes, please.', 'SRC-AGENT:sequencing', 'derived', null),
  (3826, 'word', 'W001253', 'ປອກ to peel (fruit or vegetables) (word 1253; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3827, 'sentence', 'S000002481', 'ມັນຕົ້ນຕ້ອງປອກເປືອກກ່ອນຕົ້ມ. Cassava must be peeled before boiling.', 'SRC-AGENT:sequencing', 'derived', null),
  (3828, 'sentence', 'S000002494', 'ແມ່ປອກຫອມແດງແລະກະທຽມ. Mother peels shallots and garlic.', 'SRC-AGENT:sequencing', 'derived', null),
  (3829, 'sentence', 'S000002543', 'ຂ້ອຍໃຊ້ມີດປອກໝາກມ່ວງ. I use a knife to peel the mango.', 'SRC-AGENT:sequencing', 'derived', null),
  (3830, 'word', 'W001254', 'ຜ່າ to split; to cut open; to cut in half (word 1254; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3831, 'sentence', 'S000002523', 'ຂ້ອຍຜ່າໝາກມັງກອນເປັນສອງສ່ວນ. I cut the dragon fruit in half.', 'SRC-AGENT:sequencing', 'derived', null),
  (3832, 'sentence', 'S000002544', 'ພໍ່ຜ່າໝາກພ້າວໃຫ້ເດັກ. Father splits a coconut for the children.', 'SRC-AGENT:sequencing', 'derived', null),
  (3833, 'word', 'W001255', 'ຫັ່ນ to cut into pieces; to slice (word 1255; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3834, 'sentence', 'S000002478', 'ແມ່ຫັ່ນກາລົດໃສ່ແກງ. Mother cuts carrots into the soup.', 'SRC-AGENT:sequencing', 'derived', null),
  (3835, 'sentence', 'S000002545', 'ແມ່ຫັ່ນໝາກໂມໃສ່ຈານ. Mother slices watermelon onto a plate.', 'SRC-AGENT:sequencing', 'derived', null),
  (3836, 'word', 'W001256', 'ຝານ to slice thinly; to shave off thin slices (word 1256; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3837, 'sentence', 'S000002546', 'ຂ້ອຍຝານໝາກແຕງໃສ່ສະຫຼັດ. I slice cucumber thinly into the salad.', 'SRC-AGENT:sequencing', 'derived', null),
  (3838, 'sentence', 'S000002547', 'ແມ່ຝານຂີງໃສ່ແກງປາ. Mother slices ginger thinly into the fish soup.', 'SRC-AGENT:sequencing', 'derived', null),
  (3839, 'word', 'W001257', 'ຊອຍ to cut finely; to shred; to slice into strips (word 1257; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3840, 'sentence', 'S000002468', 'ແມ່ຊອຍກະລຳປີໃສ່ສະຫຼັດ. Mother shreds cabbage into the salad.', 'SRC-AGENT:sequencing', 'derived', null),
  (3841, 'sentence', 'S000002548', 'ພໍ່ຊອຍຫອມແດງແລະຜັກຫອມໃສ່ລາບ. Father finely chops shallots and coriander into the laap.', 'SRC-AGENT:sequencing', 'derived', null),
  (3842, 'word', 'W001258', 'ສັບ to chop; to mince (word 1258; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3843, 'sentence', 'S000002549', 'ແມ່ສັບຊີ້ນເພື່ອເຮັດລາບ. Mother minces meat to make laap.', 'SRC-AGENT:sequencing', 'derived', null),
  (3844, 'sentence', 'S000002550', 'ຂ້ອຍສັບກະທຽມແລະໝາກເຜັດ. I chop garlic and chilies.', 'SRC-AGENT:sequencing', 'derived', null),
  (3845, 'word', 'W001259', 'ບີບ to squeeze; to press (word 1259; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3846, 'sentence', 'S000002551', 'ແມ່ຄ້າບີບໝາກນາວໃສ່ຕຳໝາກຫຸ່ງ. The vendor squeezes lime into the papaya salad.', 'SRC-AGENT:sequencing', 'derived', null),
  (3847, 'sentence', 'S000002552', 'ຂ້ອຍບີບໝາກກ້ຽງເຮັດນ້ຳໝາກໄມ້. I squeeze oranges to make juice.', 'SRC-AGENT:sequencing', 'derived', null),
  (3848, 'word', 'W001260', 'ຂູດ to scrape; to grate (coconut or carrot) (word 1260; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3849, 'sentence', 'S000002553', 'ແມ່ຂູດໝາກພ້າວເພື່ອເຮັດກະທິ. Mother grates coconut to make coconut milk.', 'SRC-AGENT:sequencing', 'derived', null),
  (3850, 'sentence', 'S000002554', 'ຂ້ອຍຂູດກາລົດໃສ່ສະຫຼັດ. I grate carrots into the salad.', 'SRC-AGENT:sequencing', 'derived', null),
  (3851, 'word', 'W001261', 'ແຊ່ to soak; to steep (word 1261; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3852, 'sentence', 'S000002437', 'ຂ້ອຍແຊ່ຖົ່ວຂຽວໃນນ້ຳໜຶ່ງຄືນ. I soak the mung beans in water for one night.', 'SRC-AGENT:sequencing', 'derived', null),
  (3853, 'sentence', 'S000002555', 'ແມ່ແຊ່ຜັກໃນນ້ຳເກືອ. Mother soaks the vegetables in salt water.', 'SRC-AGENT:sequencing', 'derived', null),
  (3854, 'word', 'W001262', 'ລວກ to blanch; to scald (dip briefly in boiling water) (word 1262; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3855, 'sentence', 'S000002474', 'ຂ້ອຍກິນຜັກກູດລວກກັບແຈ່ວ. I eat blanched fern shoots with jeow.', 'SRC-AGENT:sequencing', 'derived', null),
  (3856, 'sentence', 'S000002556', 'ແມ່ລວກຖົ່ວງອກໃນນ້ຳຮ້ອນ. Mother blanches bean sprouts in hot water.', 'SRC-AGENT:sequencing', 'derived', null),
  (3857, 'word', 'W001263', 'ດອງ to pickle; to preserve (in brine or vinegar) (word 1263; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3858, 'sentence', 'S000002557', 'ຍາຍດອງຜັກກາດທຸກປີ. Grandma pickles mustard greens every year.', 'SRC-AGENT:sequencing', 'derived', null),
  (3859, 'sentence', 'S000002558', 'ໝາກມ່ວງດອງສົ້ມແລະເຄັມ. Pickled mango is sour and salty.', 'SRC-AGENT:sequencing', 'derived', null),
  (3860, 'word', 'W001264', 'ຜັກດອງ pickled vegetables (word 1264; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3861, 'sentence', 'S000002559', 'ຂ້ອຍກິນເຂົ້າກັບຜັກດອງ. I eat rice with pickled vegetables.', 'SRC-AGENT:sequencing', 'derived', null),
  (3862, 'sentence', 'S000002560', 'ຜັກດອງຖົງນີ້ສົ້ມໂພດ. This bag of pickled vegetables is too sour.', 'SRC-AGENT:sequencing', 'derived', null),
  (3863, 'word', 'W001265', 'ເດັດ to pick; to pluck; to snap off (fruit; leaves; flowers) (word 1265; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3864, 'sentence', 'S000002561', 'ເດັກເດັດໝາກໄມ້ຈາກຕົ້ນ. The children pick fruit from the tree.', 'SRC-AGENT:sequencing', 'derived', null),
  (3865, 'sentence', 'S000002562', 'ແມ່ເດັດໃບໝາກຂີ້ຫູດສາມໃບ. Mother picks three kaffir lime leaves.', 'SRC-AGENT:sequencing', 'derived', null),
  (3866, 'word', 'W001266', 'ຊັ່ງ to weigh (on a scale) (word 1266; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3867, 'sentence', 'S000002563', 'ແມ່ຄ້າຊັ່ງໝາກມ່ວງໃຫ້ຂ້ອຍ. The vendor weighs the mangoes for me.', 'SRC-AGENT:sequencing', 'derived', null),
  (3868, 'sentence', 'S000002564', 'ຂໍຊັ່ງຖົ່ວດິນສອງກິໂລແດ່. Please weigh out two kilos of peanuts.', 'SRC-AGENT:sequencing', 'derived', null),
  (3869, 'word', 'W001267', 'ຂີດ 100 grams (market weight unit); line; mark (word 1267; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (3870, 'sentence', 'S000002565', 'ຂໍເຫັດຫອມສອງຂີດແດ່. Two hundred grams of shiitake mushrooms, please.', 'SRC-AGENT:sequencing', 'derived', null),
  (3871, 'sentence', 'S000002566', 'ໝາກຂາມຫ້າຂີດລາຄາເທົ່າໃດ? How much is five hundred grams of tamarind?', 'SRC-AGENT:sequencing', 'derived', null),
