  (4098, 'sentence', 'S000002712', 'ເດັກບໍ່ມັກໄຂ່ແດງ. The child doesn''t like egg yolk.', 'SRC-AGENT:sequencing', 'derived', null),
  (4099, 'sentence', 'S000002713', 'ໄຂ່ແດງມີສີເຫຼືອງ. Egg yolk is yellow.', 'SRC-AGENT:sequencing', 'derived', null),
  (4100, 'word', 'W001343', 'ໄຂ່ຂາວ egg white (word 1343; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4101, 'sentence', 'S000002714', 'ຂ້ອຍກິນພຽງແຕ່ໄຂ່ຂາວ. I only eat egg whites.', 'SRC-AGENT:sequencing', 'derived', null),
  (4102, 'sentence', 'S000002715', 'ແຍກໄຂ່ແດງອອກຈາກໄຂ່ຂາວ. Separate the yolk from the white.', 'SRC-AGENT:sequencing', 'derived', null),
  (4103, 'word', 'W001344', 'ປາໝຶກ squid (word 1344; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4104, 'sentence', 'S000002716', 'ປາໝຶກປີ້ງແຊບຫຼາຍ. Grilled squid is very delicious.', 'SRC-AGENT:sequencing', 'derived', null),
  (4105, 'sentence', 'S000002717', 'ຮ້ານອາຫານນີ້ມີປາໝຶກທອດບໍ່? Does this restaurant have fried squid?', 'SRC-AGENT:sequencing', 'derived', null),
  (4106, 'word', 'W001345', 'ຫອຍ snail; shellfish (clams; mussels) (word 1345; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4107, 'sentence', 'S000002718', 'ເດັກເກັບຫອຍຢູ່ໃນນາ. The children collect snails in the rice field.', 'SRC-AGENT:sequencing', 'derived', null),
  (4108, 'sentence', 'S000002719', 'ແມ່ເຮັດແກງຫອຍ. Mother makes snail soup.', 'SRC-AGENT:sequencing', 'derived', null),
  (4109, 'word', 'W001346', 'ປາແຫ້ງ dried fish (word 1346; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4110, 'sentence', 'S000002720', 'ປາແຫ້ງເຄັມຫຼາຍ. Dried fish is very salty.', 'SRC-AGENT:sequencing', 'derived', null),
  (4111, 'sentence', 'S000002721', 'ແມ່ທອດປາແຫ້ງກິນກັບເຂົ້າໜຽວ. Mother fries dried fish to eat with sticky rice.', 'SRC-AGENT:sequencing', 'derived', null),
  (4112, 'word', 'W001347', 'ໜຶ້ງ to steam (food) (word 1347; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4113, 'sentence', 'S000002722', 'ແມ່ໜຶ້ງປາໃນໝໍ້. Mother steams fish in a pot.', 'SRC-AGENT:sequencing', 'derived', null),
  (4114, 'sentence', 'S000002723', 'ທຸກເຊົ້າແມ່ໜຶ້ງເຂົ້າໜຽວ. Every morning mother steams sticky rice.', 'SRC-AGENT:sequencing', 'derived', null),
  (4115, 'word', 'W001348', 'ອົບ to bake; to roast (in an oven) (word 1348; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4116, 'sentence', 'S000002724', 'ຮ້ານນີ້ຂາຍເປັດອົບ. This shop sells roast duck.', 'SRC-AGENT:sequencing', 'derived', null),
  (4117, 'sentence', 'S000002725', 'ພໍ່ອົບເຂົ້າຈີ່ທຸກເຊົ້າ. Father bakes bread every morning.', 'SRC-AGENT:sequencing', 'derived', null),
  (4118, 'word', 'W001349', 'ໝັກ to marinate; to ferment (word 1349; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4119, 'sentence', 'S000002726', 'ແມ່ໝັກຊີ້ນກັບກະທຽມແລະເກືອ. Mother marinates the meat with garlic and salt.', 'SRC-AGENT:sequencing', 'derived', null),
  (4120, 'sentence', 'S000002727', 'ໝັກໄກ່ໜຶ່ງຄືນກ່ອນປີ້ງ. Marinate the chicken for one night before grilling.', 'SRC-AGENT:sequencing', 'derived', null),
  (4121, 'word', 'W001350', 'ກ້ອຍ koi (salad of raw or seared minced meat or fish) (word 1350; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4122, 'sentence', 'S000002728', 'ກ້ອຍແມ່ນອາຫານລາວ. Koi is a Lao dish.', 'SRC-AGENT:sequencing', 'derived', null),
  (4123, 'sentence', 'S000002729', 'ຂ້ອຍບໍ່ກິນກ້ອຍເພາະຊີ້ນດິບ. I don''t eat koi because the meat is raw.', 'SRC-AGENT:sequencing', 'derived', null),
  (4124, 'word', 'W001351', 'ຜູ້ person (who); one who (forms nouns for people); male (of animals) (word 1351; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4125, 'sentence', 'S000002730', 'ຜູ້ທີ່ມາຊ້າຕ້ອງລໍຖ້າ. Whoever comes late has to wait.', 'SRC-AGENT:sequencing', 'derived', null),
  (4126, 'sentence', 'S000002731', 'ລາວເປັນຜູ້ທີ່ຂັບລົດໄວທີ່ສຸດ. He is the one who drives the fastest.', 'SRC-AGENT:sequencing', 'derived', null),
  (4127, 'word', 'W001352', 'ຜູ້ໂດຍສານ passenger (word 1352; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4128, 'sentence', 'S000002732', 'ລົດເມຄັນນີ້ມີຜູ້ໂດຍສານຫຼາຍ. This bus has a lot of passengers.', 'SRC-AGENT:sequencing', 'derived', null),
  (4129, 'word', 'W001353', 'ຄົນຂັບລົດ driver (word 1353; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4130, 'sentence', 'S000002734', 'ຄົນຂັບລົດຄົນນີ້ໃຈດີຫຼາຍ. This driver is very kind.', 'SRC-AGENT:sequencing', 'derived', null),
  (4131, 'sentence', 'S000002735', 'ອ້າຍຂອງຂ້ອຍເປັນຄົນຂັບລົດ. My older brother is a driver.', 'SRC-AGENT:sequencing', 'derived', null),
  (4132, 'word', 'W001354', 'ໃບຂັບຂີ່ driving licence (word 1354; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4133, 'sentence', 'S000002736', 'ເຈົ້າມີໃບຂັບຂີ່ບໍ່? Do you have a driving licence?', 'SRC-AGENT:sequencing', 'derived', null),
  (4134, 'sentence', 'S000002737', 'ຕຳຫຼວດຂໍເບິ່ງໃບຂັບຂີ່ຂອງຂ້ອຍ. The police officer asked to see my driving licence.', 'SRC-AGENT:sequencing', 'derived', null),
  (4135, 'word', 'W001355', 'ຄ່າໂດຍສານ fare (passenger fare) (word 1355; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4136, 'sentence', 'S000002738', 'ຄ່າໂດຍສານເທົ່າໃດ? How much is the fare?', 'SRC-AGENT:sequencing', 'derived', null),
  (4137, 'sentence', 'S000002739', 'ຄ່າໂດຍສານໄປປາກເຊແມ່ນສອງແສນກີບ. The fare to Pakse is 200000 kip.', 'SRC-AGENT:sequencing', 'derived', null),
  (4138, 'word', 'W001356', 'ລົດໂດຍສານ coach; long-distance passenger bus (word 1356; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4139, 'sentence', 'S000002740', 'ຂ້ອຍຈະໄປຫຼວງພະບາງໂດຍລົດໂດຍສານ. I will go to Luang Prabang by coach.', 'SRC-AGENT:sequencing', 'derived', null),
  (4140, 'sentence', 'S000002741', 'ລົດໂດຍສານອອກຕອນແປດໂມງ. The coach leaves at eight o''clock.', 'SRC-AGENT:sequencing', 'derived', null),
  (4141, 'word', 'W001357', 'ເຕີມນ້ຳມັນ refuel; fill up with petrol (word 1357; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4142, 'sentence', 'S000002742', 'ຂ້ອຍຕ້ອງເຕີມນ້ຳມັນກ່ອນ. I have to fill up with petrol first.', 'SRC-AGENT:sequencing', 'derived', null),
  (4143, 'sentence', 'S000002743', 'ພໍ່ໄປເຕີມນ້ຳມັນຢູ່ປ້ຳນ້ຳມັນ. Father went to fill up at the petrol station.', 'SRC-AGENT:sequencing', 'derived', null),
  (4144, 'word', 'W001358', 'ລໍ້ wheel (word 1358; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4145, 'sentence', 'S000002744', 'ລົດຈັກມີສອງລໍ້. A motorbike has two wheels.', 'SRC-AGENT:sequencing', 'derived', null),
  (4146, 'word', 'W001359', 'ຢາງ rubber; tyre (word 1359; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4147, 'sentence', 'S000002747', 'ຢາງລົດຈັກບໍ່ມີລົມ. The motorbike tyre is flat (has no air).', 'SRC-AGENT:sequencing', 'derived', null),
  (4148, 'word', 'W001360', 'ແຕກ break; burst; crack (of glass or a tyre) (word 1360; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4149, 'sentence', 'S000002746', 'ຢາງລົດຂອງຂ້ອຍແຕກ. My car tyre burst.', 'SRC-AGENT:sequencing', 'derived', null),
  (4150, 'sentence', 'S000002748', 'ແກ້ວແຕກແລ້ວ. The glass has broken.', 'SRC-AGENT:sequencing', 'derived', null),
  (4151, 'word', 'W001361', 'ເພ be broken; break down (of machines and vehicles) (word 1361; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4152, 'sentence', 'S000002745', 'ລໍ້ລົດຖີບຂອງຂ້ອຍເພ. The wheel of my bicycle is broken.', 'SRC-AGENT:sequencing', 'derived', null),
  (4153, 'sentence', 'S000002749', 'ລົດຂອງລາວເພຢູ່ທາງຫຼວງ. His car broke down on the highway.', 'SRC-AGENT:sequencing', 'derived', null),
  (4154, 'word', 'W001362', 'ຮ້ານສ້ອມລົດ car repair shop; garage (word 1362; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4155, 'sentence', 'S000002750', 'ຂ້ອຍເອົາລົດໄປຮ້ານສ້ອມລົດ. I took the car to the repair shop.', 'SRC-AGENT:sequencing', 'derived', null),
  (4156, 'sentence', 'S000002751', 'ຮ້ານສ້ອມລົດຢູ່ໃກ້ປ້ຳນ້ຳມັນ. The repair shop is near the petrol station.', 'SRC-AGENT:sequencing', 'derived', null),
  (4157, 'word', 'W001363', 'ເຄື່ອງຈັກ engine; machine (word 1363; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4158, 'sentence', 'S000002752', 'ເຄື່ອງຈັກລົດຄັນນີ້ເກົ່າແລ້ວ. The engine of this car is old now.', 'SRC-AGENT:sequencing', 'derived', null),
  (4159, 'sentence', 'S000002753', 'ຊ່າງກຳລັງແກ້ເຄື່ອງຈັກ. The mechanic is fixing the engine.', 'SRC-AGENT:sequencing', 'derived', null),
  (4160, 'word', 'W001364', 'ຄວາມໄວ speed (word 1364; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4161, 'sentence', 'S000002754', 'ຄວາມໄວຂອງລົດໄຟແມ່ນເທົ່າໃດ? What is the speed of the train?', 'SRC-AGENT:sequencing', 'derived', null),
  (4162, 'sentence', 'S000002755', 'ຄວາມໄວໃນເມືອງບໍ່ຄວນເກີນຫ້າສິບກິໂລ. Speed in town should not go over fifty kilometres (an hour).', 'SRC-AGENT:sequencing', 'derived', null),
  (4163, 'word', 'W001365', 'ຈະລາຈອນ traffic (word 1365; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4164, 'sentence', 'S000002756', 'ຈະລາຈອນໃນວຽງຈັນຕິດຫຼາຍ. The traffic in Vientiane is very jammed.', 'SRC-AGENT:sequencing', 'derived', null),
  (4165, 'sentence', 'S000002757', 'ຕຳຫຼວດຈະລາຈອນຢືນຢູ່ສີ່ແຍກ. The traffic police are standing at the intersection.', 'SRC-AGENT:sequencing', 'derived', null),
  (4166, 'word', 'W001366', 'ໄຟຂຽວ green light (traffic signal) (word 1366; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4167, 'sentence', 'S000002758', 'ໄຟຂຽວແລ້ວໄປໄດ້. The light is green now; we can go.', 'SRC-AGENT:sequencing', 'derived', null),
  (4168, 'sentence', 'S000002759', 'ລໍຖ້າໄຟຂຽວກ່ອນ. Wait for the green light first.', 'SRC-AGENT:sequencing', 'derived', null),
  (4169, 'word', 'W001367', 'ທາງມ້າລາຍ zebra crossing; pedestrian crossing (word 1367; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4170, 'sentence', 'S000002760', 'ຂ້າມຖະໜົນຢູ່ທາງມ້າລາຍ. Cross the street at the zebra crossing.', 'SRC-AGENT:sequencing', 'derived', null),
  (4171, 'sentence', 'S000002761', 'ລົດຕ້ອງຢຸດຢູ່ທາງມ້າລາຍ. Cars must stop at the zebra crossing.', 'SRC-AGENT:sequencing', 'derived', null),
  (4172, 'word', 'W001368', 'ທາງຍ່າງ sidewalk; footpath; walkway (word 1368; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4173, 'sentence', 'S000002762', 'ຍ່າງຢູ່ທາງຍ່າງເດີ. Walk on the sidewalk, OK?', 'SRC-AGENT:sequencing', 'derived', null),
  (4174, 'sentence', 'S000002763', 'ທາງຍ່າງນີ້ແຄບຫຼາຍ. This sidewalk is very narrow.', 'SRC-AGENT:sequencing', 'derived', null),
  (4175, 'word', 'W001369', 'ສາມແຍກ T-junction; three-way intersection (word 1369; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4176, 'sentence', 'S000002764', 'ຮອດສາມແຍກແລ້ວລ້ຽວຊ້າຍ. When you reach the T-junction, turn left.', 'SRC-AGENT:sequencing', 'derived', null),
  (4177, 'sentence', 'S000002765', 'ໂຮງຮຽນຢູ່ໃກ້ສາມແຍກ. The school is near the T-junction.', 'SRC-AGENT:sequencing', 'derived', null),
  (4178, 'word', 'W001370', 'ວົງວຽນ roundabout; traffic circle (word 1370; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4179, 'sentence', 'S000002766', 'ໄປຊື່ໆຮອດວົງວຽນ. Go straight to the roundabout.', 'SRC-AGENT:sequencing', 'derived', null),
  (4180, 'word', 'W001371', 'ແຈ corner (of a street or room) (word 1371; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4181, 'sentence', 'S000002768', 'ຮ້ານກາເຟຢູ່ແຈຖະໜົນ. The cafe is on the street corner.', 'SRC-AGENT:sequencing', 'derived', null),
  (4182, 'sentence', 'S000002769', 'ລ້ຽວຂວາຢູ່ແຈນັ້ນ. Turn right at that corner.', 'SRC-AGENT:sequencing', 'derived', null),
  (4183, 'word', 'W001372', 'ກົງກັນຂ້າມ opposite; across from (word 1372; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4184, 'sentence', 'S000002770', 'ທະນາຄານຢູ່ກົງກັນຂ້າມກັບໂຮງແຮມ. The bank is opposite the hotel.', 'SRC-AGENT:sequencing', 'derived', null),
  (4185, 'sentence', 'S000002771', 'ຕະຫຼາດຢູ່ກົງກັນຂ້າມວັດ. The market is across from the temple.', 'SRC-AGENT:sequencing', 'derived', null),
  (4186, 'word', 'W001373', 'ຕິດກັບ next to; adjacent to (word 1373; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4187, 'sentence', 'S000002772', 'ຮ້ານຢາຢູ່ຕິດກັບໄປສະນີ. The pharmacy is next to the post office.', 'SRC-AGENT:sequencing', 'derived', null),
  (4188, 'sentence', 'S000002773', 'ເຮືອນຂອງຂ້ອຍຢູ່ຕິດກັບໂຮງຮຽນ. My house is next to the school.', 'SRC-AGENT:sequencing', 'derived', null),
  (4189, 'word', 'W001374', 'ຂ້າງໜ້າ in front; ahead (word 1374; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4190, 'sentence', 'S000002774', 'ມີລົດຕິດຢູ່ຂ້າງໜ້າ. There is a traffic jam ahead.', 'SRC-AGENT:sequencing', 'derived', null),
  (4191, 'sentence', 'S000002775', 'ຈອດລົດຢູ່ຂ້າງໜ້າໂຮງແຮມໄດ້ບໍ່? Can I park in front of the hotel?', 'SRC-AGENT:sequencing', 'derived', null),
  (4192, 'word', 'W001375', 'ຂ້າງຫຼັງ behind; at the back (word 1375; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4193, 'sentence', 'S000002776', 'ກະເປົາຢູ່ຂ້າງຫຼັງລົດ. The bag is behind the car.', 'SRC-AGENT:sequencing', 'derived', null),
  (4194, 'sentence', 'S000002777', 'ສວນຢູ່ຂ້າງຫຼັງເຮືອນ. The garden is behind the house.', 'SRC-AGENT:sequencing', 'derived', null),
  (4195, 'word', 'W001376', 'ຂວາມື right-hand side; on the right (word 1376; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4196, 'sentence', 'S000002778', 'ທະນາຄານຢູ່ຂວາມື. The bank is on the right-hand side.', 'SRC-AGENT:sequencing', 'derived', null),
  (4197, 'sentence', 'S000002779', 'ລ້ຽວຂວາແລ້ວໂຮງໝໍຢູ່ຂວາມື. Turn right and the hospital is on your right.', 'SRC-AGENT:sequencing', 'derived', null),
  (4198, 'word', 'W001377', 'ຊ້າຍມື left-hand side; on the left (word 1377; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4199, 'sentence', 'S000002780', 'ໄປສະນີຢູ່ຊ້າຍມື. The post office is on the left-hand side.', 'SRC-AGENT:sequencing', 'derived', null),
  (4200, 'sentence', 'S000002781', 'ວັດຢູ່ຊ້າຍມືຂອງຖະໜົນ. The temple is on the left side of the road.', 'SRC-AGENT:sequencing', 'derived', null),
