  (4202, 'sentence', 'S000002767', 'ປະຕູໄຊຢູ່ກາງວົງວຽນ. Patuxai is in the middle of the roundabout.', 'SRC-AGENT:sequencing', 'derived', null),
  (4203, 'sentence', 'S000002782', 'ບໍ່ຄວນຈອດລົດຢູ່ກາງທາງ. You should not park in the middle of the road.', 'SRC-AGENT:sequencing', 'derived', null),
