  (4214, 'sentence', 'S000002789', 'ຂ້ອຍຢາກໄປຫ້າງ. I want to go to the mall.', 'SRC-AGENT:sequencing', 'derived', null),
  (4215, 'sentence', 'S000002790', 'ຫ້າງນີ້ເປີດທຸກມື້. This department store is open every day.', 'SRC-AGENT:sequencing', 'derived', null),
  (4216, 'word', 'W001383', 'ອະນຸສາວະລີ monument (word 1383; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4217, 'sentence', 'S000002791', 'ອະນຸສາວະລີຢູ່ໃຈກາງເມືອງ. The monument is in the city centre.', 'SRC-AGENT:sequencing', 'derived', null),
  (4218, 'sentence', 'S000002792', 'ລ້ຽວຊ້າຍຢູ່ອະນຸສາວະລີ. Turn left at the monument.', 'SRC-AGENT:sequencing', 'derived', null),
  (4219, 'word', 'W001384', 'ປ້າຍລົດເມ bus stop (word 1384; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4220, 'sentence', 'S000002793', 'ປ້າຍລົດເມຢູ່ໃສ? Where is the bus stop?', 'SRC-AGENT:sequencing', 'derived', null),
  (4221, 'sentence', 'S000002794', 'ຂ້ອຍລໍຖ້າລົດເມຢູ່ປ້າຍລົດເມ. I am waiting for the bus at the bus stop.', 'SRC-AGENT:sequencing', 'derived', null),
