  (4223, 'sentence', 'S000002795', 'ລໍຖ້າຄິວແດ່. Please wait your turn.', 'SRC-AGENT:sequencing', 'derived', null),
  (4224, 'sentence', 'S000002796', 'ຕອນນີ້ແມ່ນຄິວຂອງເຈົ້າ. Now it is your turn.', 'SRC-AGENT:sequencing', 'derived', null),
  (4225, 'word', 'W001386', 'ຄິວລົດ bus or minivan terminal (colloquial) (word 1386; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4226, 'sentence', 'S000002797', 'ຄິວລົດຢູ່ໃກ້ຕະຫຼາດເຊົ້າ. The bus terminal is near the Morning Market.', 'SRC-AGENT:sequencing', 'derived', null),
  (4227, 'sentence', 'S000002798', 'ລົດຕູ້ອອກຈາກຄິວລົດທຸກຊົ່ວໂມງ. Minivans leave the terminal every hour.', 'SRC-AGENT:sequencing', 'derived', null),
  (4228, 'word', 'W001387', 'ຂາໄປ the way there; outbound trip (word 1387; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4229, 'sentence', 'S000002799', 'ຂາໄປໃຊ້ເວລາສີ່ຊົ່ວໂມງ. The trip there takes four hours.', 'SRC-AGENT:sequencing', 'derived', null),
  (4230, 'word', 'W001388', 'ຂາກັບ the way back; return trip (word 1388; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4231, 'sentence', 'S000002800', 'ຂາໄປຂ້ອຍນັ່ງລົດໄຟແຕ່ຂາກັບຂ້ອຍນັ່ງເຮືອບິນ. On the way there I took the train, but on the way back I flew.', 'SRC-AGENT:sequencing', 'derived', null),
  (4232, 'sentence', 'S000002801', 'ຂາກັບລົດຕິດຫຼາຍ. On the way back the traffic was very heavy.', 'SRC-AGENT:sequencing', 'derived', null),
  (4233, 'word', 'W001389', 'ຖ້ຽວ trip; run (of a bus or flight); time (word 1389; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4234, 'sentence', 'S000002802', 'ມື້ໜຶ່ງມີລົດເມສາມຖ້ຽວ. There are three bus runs a day.', 'SRC-AGENT:sequencing', 'derived', null),
  (4235, 'sentence', 'S000002803', 'ຖ້ຽວສຸດທ້າຍອອກຕອນຫ້າໂມງແລງ. The last run leaves at five in the evening.', 'SRC-AGENT:sequencing', 'derived', null),
