  (4239, 'sentence', 'S000002804', 'ຖ້ຽວບິນໄປຫຼວງພະບາງລ່າຊ້າ. The flight to Luang Prabang is delayed.', 'SRC-AGENT:sequencing', 'derived', null),
  (4240, 'sentence', 'S000002806', 'ລົດໄຟລ່າຊ້າສາມສິບນາທີ. The train is thirty minutes late.', 'SRC-AGENT:sequencing', 'derived', null),
  (4241, 'word', 'W001392', 'ຂົນສົ່ງ transport; carry (goods); transportation (word 1392; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4242, 'sentence', 'S000002807', 'ບໍລິສັດນີ້ຂົນສົ່ງເຄື່ອງໄປປາກເຊ. This company transports goods to Pakse.', 'SRC-AGENT:sequencing', 'derived', null),
  (4243, 'word', 'W001393', 'ລົດບັນທຸກ truck; lorry (word 1393; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4244, 'sentence', 'S000002808', 'ລົດບັນທຸກໃຊ້ຂົນສົ່ງເຂົ້າ. Trucks are used to transport rice.', 'SRC-AGENT:sequencing', 'derived', null),
  (4245, 'sentence', 'S000002809', 'ລົດບັນທຸກຄັນໃຫຍ່ຈອດຢູ່ທາງຫຼວງ. A big truck is parked on the highway.', 'SRC-AGENT:sequencing', 'derived', null),
  (4246, 'word', 'W001394', 'ເສັ້ນທາງ route; way; road (word 1394; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4247, 'sentence', 'S000002810', 'ເສັ້ນທາງນີ້ໄປຫຼວງພະບາງ. This route goes to Luang Prabang.', 'SRC-AGENT:sequencing', 'derived', null),
  (4248, 'sentence', 'S000002811', 'ເສັ້ນທາງໄປປາກເຊຍາວຫຼາຍ. The road to Pakse is very long.', 'SRC-AGENT:sequencing', 'derived', null),
  (4249, 'word', 'W001395', 'ກິໂລແມັດ kilometre (word 1395; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4250, 'sentence', 'S000002812', 'ຈາກນີ້ໄປສະໜາມບິນປະມານຫ້າກິໂລແມັດ. From here to the airport is about five kilometres.', 'SRC-AGENT:sequencing', 'derived', null),
  (4251, 'sentence', 'S000002813', 'ຂ້ອຍແລ່ນສາມກິໂລແມັດທຸກເຊົ້າ. I run three kilometres every morning.', 'SRC-AGENT:sequencing', 'derived', null),
  (4252, 'word', 'W001396', 'ໄລຍະທາງ distance (word 1396; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4253, 'sentence', 'S000002814', 'ໄລຍະທາງຈາກວຽງຈັນໄປຫຼວງພະບາງແມ່ນເທົ່າໃດ? What is the distance from Vientiane to Luang Prabang?', 'SRC-AGENT:sequencing', 'derived', null),
