  (4256, 'sentence', 'S000002816', 'ລາວຮູ້ຈັກທາງລັດ. She knows a shortcut.', 'SRC-AGENT:sequencing', 'derived', null),
  (4257, 'sentence', 'S000002817', 'ໄປທາງລັດໄວກວ່າ. Taking the shortcut is faster.', 'SRC-AGENT:sequencing', 'derived', null),
