  (4259, 'sentence', 'S000002818', 'ຖອຍລົດຊ້າໆແດ່. Please reverse the car slowly.', 'SRC-AGENT:sequencing', 'derived', null),
  (4260, 'sentence', 'S000002819', 'ຖອຍຫຼັງອີກໜ້ອຍໜຶ່ງ. Back up a little more.', 'SRC-AGENT:sequencing', 'derived', null),
