  (4262, 'sentence', 'S000002820', 'ບໍ່ຄວນແຊງລົດຢູ່ຂົວ. You should not overtake on the bridge.', 'SRC-AGENT:sequencing', 'derived', null),
  (4263, 'sentence', 'S000002821', 'ລົດຈັກແຊງລົດເມໄວຫຼາຍ. The motorbike overtook the bus very fast.', 'SRC-AGENT:sequencing', 'derived', null),
