  (4265, 'sentence', 'S000002822', 'ລົດສອງຄັນຊົນກັນຢູ່ສີ່ແຍກ. Two cars collided at the intersection.', 'SRC-AGENT:sequencing', 'derived', null),
  (4266, 'sentence', 'S000002823', 'ລົດຖີບຊົນຕົ້ນໄມ້. The bicycle crashed into a tree.', 'SRC-AGENT:sequencing', 'derived', null),
