  (4268, 'sentence', 'S000002824', 'ຄົນຫຼາຍຢືນເປັນແຖວ. Many people stood in a line.', 'SRC-AGENT:sequencing', 'derived', null),
  (4269, 'sentence', 'S000002825', 'ເຮືອນລາວຢູ່ແຖວຕະຫຼາດ. Her house is near the market (in the market area).', 'SRC-AGENT:sequencing', 'derived', null),
  (4270, 'word', 'W001402', 'ລົດສອງແຖວ songthaew (pickup truck with two benches used as a shared taxi) (word 1402; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4271, 'sentence', 'S000002826', 'ລົດສອງແຖວໄປຕະຫຼາດເຊົ້າ. The songthaew goes to the Morning Market.', 'SRC-AGENT:sequencing', 'derived', null),
  (4272, 'sentence', 'S000002827', 'ເຮົານັ່ງລົດສອງແຖວໄປບ້ານຍາຍ. We took a songthaew to Grandma''s house.', 'SRC-AGENT:sequencing', 'derived', null),
  (4273, 'word', 'W001403', 'ລົດເກັງ car (sedan; saloon) (word 1403; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4274, 'sentence', 'S000002828', 'ລາວຊື້ລົດເກັງຄັນໃໝ່. He bought a new car.', 'SRC-AGENT:sequencing', 'derived', null),
  (4275, 'sentence', 'S000002829', 'ລົດເກັງຄັນສີດຳຈອດຢູ່ຂ້າງນອກ. The black car is parked outside.', 'SRC-AGENT:sequencing', 'derived', null),
