  (4277, 'sentence', 'S000002830', 'ເຮົາຈະໄປປາກເຊໂດຍລົດນອນ. We will go to Pakse by sleeper bus.', 'SRC-AGENT:sequencing', 'derived', null),
  (4278, 'sentence', 'S000002831', 'ລົດນອນອອກຕອນແປດໂມງແລງ. The sleeper bus leaves at eight in the evening.', 'SRC-AGENT:sequencing', 'derived', null),
  (4279, 'word', 'W001405', 'ສະຖານີລົດໄຟ train station; railway station (word 1405; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4280, 'sentence', 'S000002832', 'ສະຖານີລົດໄຟຢູ່ໄກຈາກໃຈກາງເມືອງ. The train station is far from the city centre.', 'SRC-AGENT:sequencing', 'derived', null),
  (4281, 'sentence', 'S000002833', 'ໄປສະຖານີລົດໄຟເທົ່າໃດ? How much is it to the train station?', 'SRC-AGENT:sequencing', 'derived', null),
