  (4283, 'sentence', 'S000002834', 'ເຮືອອອກຈາກທ່າເຮືອຕອນເຊົ້າ. The boat leaves the pier in the morning.', 'SRC-AGENT:sequencing', 'derived', null),
  (4284, 'sentence', 'S000002835', 'ທ່າເຮືອຢູ່ແຄມແມ່ນ້ຳຂອງ. The pier is on the bank of the Mekong.', 'SRC-AGENT:sequencing', 'derived', null),
  (4285, 'word', 'W001407', 'ຟາກ side (of a river or road); bank; the other side (word 1407; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4286, 'sentence', 'S000002836', 'ຟາກນັ້ນແມ່ນປະເທດໄທ. The other side is Thailand.', 'SRC-AGENT:sequencing', 'derived', null),
  (4287, 'word', 'W001408', 'ເຮືອຂ້າມຟາກ ferry (word 1408; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4288, 'sentence', 'S000002837', 'ຂ້ອຍຂ້າມໄປຟາກນັ້ນໂດຍເຮືອຂ້າມຟາກ. I crossed to the other side by ferry.', 'SRC-AGENT:sequencing', 'derived', null),
  (4289, 'sentence', 'S000002838', 'ເຮືອຂ້າມຟາກມີທຸກຊົ່ວໂມງ. There is a ferry every hour.', 'SRC-AGENT:sequencing', 'derived', null),
  (4290, 'word', 'W001409', 'ຂຶ້ນລົດ get on or into a vehicle (word 1409; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4291, 'sentence', 'S000002839', 'ຂຶ້ນລົດໄວໆເພາະລົດຈະອອກແລ້ວ. Get on quickly because the bus is about to leave.', 'SRC-AGENT:sequencing', 'derived', null),
  (4292, 'sentence', 'S000002840', 'ເຮົາຂຶ້ນລົດຢູ່ສະຖານີລົດເມ. We got on the bus at the bus station.', 'SRC-AGENT:sequencing', 'derived', null),
  (4293, 'word', 'W001410', 'ລົງລົດ get off or out of a vehicle (word 1410; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4294, 'sentence', 'S000002733', 'ຜູ້ໂດຍສານຕ້ອງລົງລົດຢູ່ນີ້. Passengers must get off here.', 'SRC-AGENT:sequencing', 'derived', null),
  (4295, 'sentence', 'S000002841', 'ຂ້ອຍຈະລົງລົດຢູ່ສີ່ແຍກ. I will get off at the intersection.', 'SRC-AGENT:sequencing', 'derived', null),
  (4296, 'word', 'W001411', 'ກະເປົາເດີນທາງ suitcase; travel bag (word 1411; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4297, 'sentence', 'S000002842', 'ກະເປົາເດີນທາງຂອງຂ້ອຍໜັກຫຼາຍ. My suitcase is very heavy.', 'SRC-AGENT:sequencing', 'derived', null),
  (4298, 'sentence', 'S000002843', 'ວາງກະເປົາເດີນທາງຢູ່ເທິງລົດ. Put the suitcase on top of the vehicle.', 'SRC-AGENT:sequencing', 'derived', null),
  (4299, 'word', 'W001412', 'ເມົາ be drunk; be dizzy (word 1412; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4300, 'sentence', 'S000002844', 'ຖ້າເມົາບໍ່ຄວນຂັບລົດ. If you are drunk, you should not drive.', 'SRC-AGENT:sequencing', 'derived', null),
  (4301, 'sentence', 'S000002845', 'ລາວດື່ມເບຍຫຼາຍຈົນເມົາ. He drank so much beer that he got drunk.', 'SRC-AGENT:sequencing', 'derived', null),
  (4302, 'word', 'W001413', 'ເມົາລົດ be carsick; get travel sickness (word 1413; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4303, 'sentence', 'S000002846', 'ຂ້ອຍເມົາລົດທຸກເທື່ອ. I get carsick every time.', 'SRC-AGENT:sequencing', 'derived', null),
  (4304, 'sentence', 'S000002847', 'ຖ້າເມົາລົດໃຫ້ກິນຢາກ່ອນ. If you get carsick, take some medicine first.', 'SRC-AGENT:sequencing', 'derived', null),
  (4305, 'word', 'W001414', 'ທາງອອກ exit; way out (word 1414; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4306, 'sentence', 'S000002848', 'ທາງອອກຢູ່ໃສ? Where is the exit?', 'SRC-AGENT:sequencing', 'derived', null),
  (4307, 'sentence', 'S000002849', 'ທາງອອກຢູ່ທາງຂວາ. The exit is on the right.', 'SRC-AGENT:sequencing', 'derived', null),
  (4308, 'word', 'W001415', 'ທາງເຂົ້າ entrance; way in (word 1415; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4309, 'sentence', 'S000002850', 'ທາງເຂົ້າສະໜາມບິນຢູ່ທາງຊ້າຍ. The airport entrance is on the left.', 'SRC-AGENT:sequencing', 'derived', null),
  (4310, 'sentence', 'S000002851', 'ຈອດລົດຢູ່ທາງເຂົ້າບໍ່ໄດ້. You cannot park at the entrance.', 'SRC-AGENT:sequencing', 'derived', null),
  (4311, 'word', 'W001416', 'ຮ່ອມ lane; alley; side street (word 1416; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4312, 'sentence', 'S000002852', 'ເຮືອນຂ້ອຍຢູ່ໃນຮ່ອມນີ້. My house is in this lane.', 'SRC-AGENT:sequencing', 'derived', null),
  (4313, 'word', 'W001417', 'ຄ່າຈອດລົດ parking fee (word 1417; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4314, 'sentence', 'S000002854', 'ຄ່າຈອດລົດເທົ່າໃດ? How much is the parking fee?', 'SRC-AGENT:sequencing', 'derived', null),
  (4315, 'sentence', 'S000002855', 'ຄ່າຈອດລົດຢູ່ສະໜາມບິນແພງ. Parking at the airport is expensive.', 'SRC-AGENT:sequencing', 'derived', null),
  (4316, 'word', 'W001418', 'ຕາມ follow; along; according to (word 1418; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4317, 'sentence', 'S000002856', 'ໄປຕາມທາງນີ້ຮອດແມ່ນ້ຳ. Follow this road to the river.', 'SRC-AGENT:sequencing', 'derived', null),
  (4318, 'sentence', 'S000002857', 'ຂັບລົດຕາມຂ້ອຍມາ. Drive behind me (follow me).', 'SRC-AGENT:sequencing', 'derived', null),
  (4319, 'word', 'W001419', 'ເລີຍ go past; go beyond; (after a verb) straight away; at all (word 1419; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4320, 'sentence', 'S000002858', 'ເລີຍສີ່ແຍກໄປໜ້ອຍໜຶ່ງ. Go a little past the intersection.', 'SRC-AGENT:sequencing', 'derived', null),
  (4321, 'sentence', 'S000002859', 'ຂ້ອຍນັ່ງລົດເມເລີຍບ້ານ. I rode the bus past my home.', 'SRC-AGENT:sequencing', 'derived', null),
  (4322, 'word', 'W001420', 'ຫ່າງ far apart; at a distance (from) (word 1420; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4323, 'sentence', 'S000002860', 'ໂຮງແຮມຢູ່ຫ່າງຈາກສະໜາມບິນສິບກິໂລ. The hotel is ten kilometres from the airport.', 'SRC-AGENT:sequencing', 'derived', null),
  (4324, 'sentence', 'S000002861', 'ບ້ານຂອງລາວຢູ່ຫ່າງຈາກເມືອງ. His village is far from town.', 'SRC-AGENT:sequencing', 'derived', null),
  (4325, 'word', 'W001421', 'ຖາມທາງ ask the way; ask for directions (word 1421; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4326, 'sentence', 'S000002862', 'ຖ້າຫຼົງທາງໃຫ້ຖາມທາງ. If you get lost, ask the way.', 'SRC-AGENT:sequencing', 'derived', null),
  (4327, 'sentence', 'S000002863', 'ຂ້ອຍຖາມທາງຕຳຫຼວດ. I asked a police officer for directions.', 'SRC-AGENT:sequencing', 'derived', null),
  (4328, 'word', 'W001422', 'ບອກທາງ give directions; show the way (word 1422; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4329, 'sentence', 'S000002864', 'ຊ່ວຍບອກທາງໄປທາດຫຼວງແດ່. Please tell me the way to That Luang.', 'SRC-AGENT:sequencing', 'derived', null),
  (4330, 'sentence', 'S000002865', 'ລາວບອກທາງໃຫ້ນັກທ່ອງທ່ຽວ. She gave directions to the tourists.', 'SRC-AGENT:sequencing', 'derived', null),
  (4331, 'word', 'W001423', 'ສູບ pump (air or water); smoke (a cigarette) (word 1423; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4332, 'sentence', 'S000002866', 'ຂ້ອຍຕ້ອງສູບລົມຢາງລົດຖີບ. I need to pump up the bicycle tyre.', 'SRC-AGENT:sequencing', 'derived', null),
  (4333, 'sentence', 'S000002867', 'ພໍ່ບໍ່ສູບຢາ. Father does not smoke.', 'SRC-AGENT:sequencing', 'derived', null),
  (4334, 'word', 'W001424', 'ທາງດ່ວນ expressway; motorway (word 1424; 0 new symbols)', 'SRC-AGENT:sequencing', 'derived', null),
  (4335, 'sentence', 'S000002868', 'ທາງດ່ວນໄວກວ່າທາງຫຼວງ. The expressway is faster than the highway.', 'SRC-AGENT:sequencing', 'derived', null),
  (4336, 'sentence', 'S000002869', 'ຕ້ອງຈ່າຍເງິນເພື່ອໃຊ້ທາງດ່ວນ. You have to pay to use the expressway.', 'SRC-AGENT:sequencing', 'derived', null),
