  (4339, 'sentence', 'S000002222', 'ຖອດເກີບກ່ອນເຂົ້າເຮືອນ. Take off your shoes before going into the house.', 'SRC-AGENT:sequencing', 'derived', null),
  (4340, 'sentence', 'S000002853', 'ລ້ຽວຊ້າຍເຂົ້າຮ່ອມທີ່ສອງ. Turn left into the second lane.', 'SRC-AGENT:sequencing', 'derived', null)
